/* Winx Club NATURE fairy wings (Flora-inspired). Right half generated, mirrored about x=128. */
var G = {};
var CX = 128, RX = 131, RY = 120, Z0 = 128;
function H(x, y, z) { var s = Math.sin(x * 12.9898 + y * 78.233 + z * 37.719) * 43758.5453; return s - Math.floor(s); }
function P(x, y, z, t) { x = Math.round(x); y = Math.round(y); z = Math.round(z); if (x < CX) return; G[x + "," + y + "," + z] = t; }
function PK(x, y, z, t) { x = Math.round(x); y = Math.round(y); z = Math.round(z); var k = x + "," + y + "," + z; if (x >= CX && !G[k]) G[k] = t; }
function D2R(a) { return a * Math.PI / 180; }

/* ---------- colour ramps ---------- */
function pink(g, r) { /* g: 0 root (deep magenta) .. 1 edge (pale pink) */
  if (g < 0.2) return r < 0.55 ? "purple_wool" : "red_wool";
  if (g < 0.42) return r < 0.2 ? "purple_wool" : (r < 0.72 ? "red_wool" : "white_wool");
  if (g < 0.7) return r < 0.5 ? "red_wool" : "white_wool";
  return r < 0.28 ? "red_wool" : "white_wool";
}
function leafc(g, r) {
  if (g < 0.3) return r < 0.6 ? "green_wool" : "oak_leaves";
  return r < 0.72 ? "oak_leaves" : "green_wool";
}

/* ---------- parametric wing surface ---------- */
function Wing(o) {
  o.ca = Math.cos(D2R(o.ang)); o.sa = Math.sin(D2R(o.ang));
  o.hw = function (t, u) {
    if (t <= 0 || t >= 1) return 0;
    var h = o.W * o.shape(t);
    if (o.serr) h *= 1 - o.serr * (((u * 0.42) % 1 + 1) % 1);
    if (o.scal) h *= 1 + o.scal * Math.sin(t * Math.PI * 7) * t;
    return h;
  };
  o.zc = function (t, v, hw) {
    var an = hw > 0 ? Math.min(1, Math.abs(v) / hw) : 0;
    var z = o.z0 + o.sweep * t * t + o.cup * (v / o.W) * (v / o.W) + (o.fold || 0) * Math.abs(v) / o.W;
    if (o.lip && an > 0.78) { var e = (an - 0.78) / 0.22; z += o.lip * e * e * (hw / o.W); }
    if (o.tip) z += o.tip * t * t * t;
    if (o.twist) z += o.twist * t * (v / o.W);
    return z;
  };
  o.world = function (t, n) { /* local -> world centre point */
    var u = t * o.L, hw = o.hw(t, u), v = n * hw;
    return { x: o.rx + u * o.ca - v * o.sa, y: o.ry + u * o.sa + v * o.ca, z: o.zc(t, v, hw), hw: hw };
  };
  return o;
}
function raster(o) {
  var x0 = 1e9, x1 = -1e9, y0 = 1e9, y1 = -1e9;
  for (var t = 0; t <= 1; t += 0.02) for (var n = -1.2; n <= 1.2; n += 0.4) {
    var u = t * o.L, v = n * o.W;
    var X = o.rx + u * o.ca - v * o.sa, Y = o.ry + u * o.sa + v * o.ca;
    x0 = Math.min(x0, X); x1 = Math.max(x1, X); y0 = Math.min(y0, Y); y1 = Math.max(y1, Y);
  }
  x0 = Math.max(CX, Math.floor(x0) - 2); x1 = Math.ceil(x1) + 2; y0 = Math.floor(y0) - 2; y1 = Math.ceil(y1) + 2;
  function samp(x, y) {
    var dx = x - o.rx, dy = y - o.ry;
    var u = dx * o.ca + dy * o.sa, v = -dx * o.sa + dy * o.ca, t = u / o.L;
    var hw = o.hw(Math.min(0.999, Math.max(0.001, t)), u);
    return { u: u, v: v, t: t, hw: hw, z: o.zc(Math.min(1, Math.max(0, t)), v, hw) };
  }
  for (var x = x0; x <= x1; x++) for (var y = y0; y <= y1; y++) {
    var s = samp(x, y);
    if (s.t < 0 || s.t > 1 || Math.abs(s.v) > s.hw) continue;
    var sR = samp(x + 1, y), sU = samp(x, y + 1), sL = samp(x - 1, y), sD = samp(x, y - 1);
    var zmn = Math.min(s.z, sR.z, sU.z, sL.z, sD.z), zmx = Math.max(s.z, sR.z, sU.z, sL.z, sD.z);
    var zlo = Math.round(Math.min(s.z, (s.z + zmn) / 2)), zhi = Math.round(Math.max(s.z, (s.z + zmx) / 2));
    var c = o.paint(s, x, y);
    var a = o.thA, b = o.thB;
    if (c.rib) { a += c.rib; b += c.rib; }
    for (var z = zlo - a; z <= zhi + b; z++) P(x, y, z, c.m);
  }
}

/* ---------- painters ---------- */
function petalPaint(deep) {
  return function (s, x, y) {
    var an = Math.abs(s.v) / s.hw, t = s.t, r = 0.6 * [0.125, 0.625, 0.875, 0.375][((x & 1) << 1) | (y & 1)] + 0.4 * H(x, y, 3);
    var mid = 1.0 + 1.6 * (1 - t);
    if (Math.abs(s.v) < mid && t < 0.9) return { m: (t < 0.28 && r < 0.5) ? "oak_leaves" : "green_wool", rib: t < 0.5 ? 2 : 1 };
    var q = s.u - 0.45 * Math.abs(s.v) - 0.018 * s.v * s.v;
    var sp = 10.5, m = ((q % sp) + sp) % sp;
    if (m < 1.5 && an < 0.84 && t > 0.1 && t < 0.9) return { m: an < 0.45 ? "green_wool" : (r < 0.6 ? "green_wool" : "oak_leaves"), rib: an < 0.5 ? 1 : 0 };
    /* fine secondary veinlets */
    var q2 = s.u + 0.9 * Math.abs(s.v), m2 = ((q2 % 21) + 21) % 21;
    if (m2 < 0.8 && an > 0.35 && an < 0.7 && t > 0.2 && t < 0.8) return { m: "oak_leaves", rib: 0 };
    if (s.hw - Math.abs(s.v) < 1.6) return { m: r < 0.18 ? "red_wool" : "white_wool", rib: 0 };
    var g = Math.min(1, 0.62 * t + 0.38 * an - deep);
    return { m: pink(g, r), rib: 0 };
  };
}
function leafPaint(s, x, y) {
  var an = Math.abs(s.v) / s.hw, r = H(x, y, 7), t = s.t;
  if (Math.abs(s.v) < 1.0 + 1.3 * (1 - t) && t < 0.95) return { m: "green_wool", rib: t < 0.6 ? 1 : 0 };
  var q = s.u - 0.75 * Math.abs(s.v), m = ((q % 8) + 8) % 8;
  if (m < 1.0 && an < 0.85 && t > 0.05 && t < 0.92) return { m: "green_wool", rib: 0 };
  if (s.hw - Math.abs(s.v) < 1.3) return { m: r < 0.8 ? "green_wool" : "oak_leaves", rib: 0 };
  /* sunlit yellow-green blush toward the tip */
  if (t > 0.72 && r < 0.12) return { m: "yellow_wool", rib: 0 };
  return { m: leafc(0.4 * t + 0.6 * an, r), rib: 0 };
}

/* ---------- the wing parts (right side) ---------- */
var upper = Wing({ rx: RX, ry: RY + 3, ang: 47, L: 106, W: 38, z0: Z0, sweep: 13, cup: -7, lip: -3, twist: 3, tip: 0, scal: 0.05,
  thA: 1, thB: 1, shape: function (t) { return Math.pow(Math.sin(Math.PI * t), 0.55) * (0.5 + 0.5 * t) / 0.83; } });
upper.paint = petalPaint(0);
var upper2 = Wing({ rx: RX + 2, ry: RY - 1, ang: 9, L: 84, W: 24, z0: Z0 + 5, sweep: 10, cup: -5, lip: -2, twist: -2, scal: 0.06,
  thA: 1, thB: 0, shape: function (t) { return Math.pow(Math.sin(Math.PI * t), 0.6) * (0.55 + 0.45 * t) / 0.84; } });
upper2.paint = petalPaint(0.22);
var midleaf = Wing({ rx: RX, ry: RY - 3, ang: -27, L: 64, W: 12, z0: Z0 + 3, sweep: 8, cup: 0, fold: -3, tip: -4, serr: 0.1,
  thA: 1, thB: 0, shape: function (t) { return Math.sin(Math.PI * Math.pow(t, 0.8)); } });
midleaf.paint = leafPaint;
var lower = Wing({ rx: RX, ry: RY - 5, ang: -64, L: 116, W: 20, z0: Z0 + 1, sweep: 9, cup: 0, fold: -4, tip: -9, twist: 2, serr: 0.08,
  thA: 1, thB: 1, shape: function (t) { return Math.sin(Math.PI * Math.pow(t, 0.75)); } });
lower.paint = leafPaint;

raster(upper2); raster(midleaf); raster(lower); raster(upper);

/* ---------- blossoms ---------- */
function flower(cx, cy, cz, R, dir, pal) {
  var rot = H(cx, cy, cz) * 6.283;
  for (var a = -R - 1; a <= R + 1; a++) for (var b = -R - 1; b <= R + 1; b++) {
    var r = Math.sqrt(a * a + b * b), th = Math.atan2(b, a) + rot;
    var rp = R * (0.38 + 0.62 * Math.pow(Math.abs(Math.cos(2.5 * th)), 0.8));
    if (r > rp + 0.3) continue;
    var h, m, hr = H(cx + a, cy + b, cz);
    if (r < 0.33 * R + 0.5) { h = 2 + Math.round((0.33 * R + 0.5 - r) * 0.9); m = (r < 0.8 && R > 4) ? "gold_block" : "yellow_wool"; }
    else {
      h = 1 + Math.round(0.32 * r * r / R);
      var f = r / R;
      m = f < 0.55 ? pal[0] : (hr < 0.5 ? pal[1] : pal[2]);
      if (f > 0.4 && Math.abs(Math.sin(2.5 * th)) < 0.08) m = pal[0];
    }
    for (var k = 0; k <= Math.max(1, h); k++) P(cx + a, cy + b, cz + dir * k, (k >= h - 1) ? m : (r < 0.33 * R + 0.5 ? "yellow_wool" : m));
  }
  /* stamens */
  for (var i = 0; i < 5; i++) { var an = rot + i * 1.2566; P(cx + Math.cos(an) * R * 0.3, cy + Math.sin(an) * R * 0.3, cz + dir * (3 + Math.round(R * 0.2)), "yellow_wool"); }
}
var PINK = ["purple_wool", "red_wool", "white_wool"], WHITE = ["yellow_wool", "white_wool", "white_wool"],
  MAG = ["red_wool", "purple_wool", "red_wool"], PALE = ["red_wool", "white_wool", "white_wool"];
function onWing(w, t, n, R, face, pal) {
  var p = w.world(t, n);
  var zf = face < 0 ? Math.round(p.z) - w.thA - 1 : Math.round(p.z) + w.thB + 1;
  flower(p.x, p.y, zf, R, face, pal);
}
/* front face (-z) */
onWing(upper, 0.93, 0.0, 6, -1, WHITE);
onWing(upper, 0.72, 0.72, 5, -1, PALE);
onWing(upper, 0.55, -0.74, 5, -1, MAG);
onWing(upper, 0.36, 0.62, 4, -1, WHITE);
onWing(upper, 0.8, -0.45, 3, -1, PINK);
onWing(upper2, 0.88, 0.1, 5, -1, PALE);
onWing(upper2, 0.55, -0.6, 3, -1, WHITE);
onWing(lower, 0.12, 0.2, 5, -1, PINK);
onWing(lower, 0.5, 0.55, 3, -1, WHITE);
onWing(midleaf, 0.55, 0.3, 3, -1, PALE);
/* back face (+z) */
onWing(upper, 0.62, 0.35, 5, 1, PALE);
onWing(upper, 0.86, -0.62, 4, 1, WHITE);
onWing(upper, 0.3, -0.5, 4, 1, MAG);
onWing(upper2, 0.7, 0.3, 4, 1, WHITE);
onWing(lower, 0.3, -0.4, 4, 1, PALE);
onWing(lower, 0.68, 0.3, 3, 1, PINK);

/* ---------- vine tendrils ---------- */
function seg(p, q, m, th) {
  var n = Math.max(Math.abs(q.x - p.x), Math.abs(q.y - p.y), Math.abs(q.z - p.z), 1) * 2;
  for (var i = 0; i <= n; i++) {
    var s = i / n, x = p.x + (q.x - p.x) * s, y = p.y + (q.y - p.y) * s, z = p.z + (q.z - p.z) * s;
    P(x, y, z, m);
    if (th) { P(x + 1, y, z, m); P(x, y + 1, z, m); P(x, y, z + 1, m); }
  }
}
function leaflet(x, y, z, ang, len) {
  var ca = Math.cos(ang), sa = Math.sin(ang);
  for (var u = 0; u <= len; u += 0.5) {
    var w = Math.sin(Math.PI * u / len) * len * 0.38;
    for (var v = -w; v <= w; v += 0.5) PK(x + u * ca - v * sa, y + u * sa + v * ca, z + (Math.abs(v) > w * 0.6 ? -1 : 0), Math.abs(v) < 0.6 ? "green_wool" : "oak_leaves");
  }
}
/* follow the rim of a wing, weaving front/back, then spiral off into a curl */
function rimVine(w, t0, t1, side, off, curlTurns, curlDir, bud) {
  var pts = [], N = 90;
  for (var i = 0; i <= N; i++) {
    var t = t0 + (t1 - t0) * i / N, p = w.world(t, side);
    var nx = -w.sa * side, ny = w.ca * side;
    pts.push({ x: p.x + nx * off, y: p.y + ny * off, z: p.z + 2.2 * Math.sin(i * 0.55) });
  }
  var L = pts.length;
  for (i = 1; i < L; i++) seg(pts[i - 1], pts[i], "green_wool", i < L * 0.5);
  for (i = 8; i < L; i += 11) {
    var pp = pts[i], dd = pts[i - 1];
    var ang = Math.atan2(pp.y - dd.y, pp.x - dd.x) + curlDir * 0.9 * (i % 22 < 11 ? 1 : -1);
    leaflet(pp.x, pp.y, pp.z + (i % 22 < 11 ? -1 : 1), ang, 5);
  }
  /* curl */
  var a = pts[L - 1], b = pts[L - 2];
  var hd = Math.atan2(a.y - b.y, a.x - b.x), x = a.x, y = a.y, z = a.z, S = curlTurns * 60, ds = 0.5;
  for (var s = 0; s < S; s += ds) {
    var k = 0.03 + 0.28 * Math.pow(s / S, 2.2);
    hd += curlDir * k * ds;
    var nx2 = x + Math.cos(hd) * ds, ny2 = y + Math.sin(hd) * ds, nz2 = z + 0.08 * Math.sin(s * 0.3);
    seg({ x: x, y: y, z: z }, { x: nx2, y: ny2, z: nz2 }, "green_wool", s < S * 0.35);
    x = nx2; y = ny2; z = nz2;
  }
  if (bud) { for (var bx = -1; bx <= 1; bx++) for (var by = -1; by <= 1; by++) for (var bz = -1; bz <= 1; bz++) if (Math.abs(bx) + Math.abs(by) + Math.abs(bz) < 3) P(x + bx, y + by, z + bz, bud); }
}
rimVine(upper, 0.12, 0.62, -1, 2.2, 1.2, 1, "red_wool");
rimVine(upper, 0.25, 0.9, 1, 2.2, 1.0, -1, "white_wool");
rimVine(upper2, 0.3, 0.85, -1, 2.0, 0.8, 1, "purple_wool");
rimVine(lower, 0.1, 0.55, 1, 2.0, 1.0, 1, "yellow_wool");
rimVine(lower, 0.2, 0.62, -1, 2.0, 0.9, -1, "red_wool");
rimVine(midleaf, 0.3, 0.8, 1, 1.8, 0.7, 1, null);

/* ---------- central blossom clasp joining the pair ---------- */
for (var dx = 0; dx <= 7; dx++) for (var dy = -9; dy <= 9; dy++) for (var dz = -5; dz <= 5; dz++) {
  var e = (dx * dx) / 36 + (dy * dy) / 81 + (dz * dz) / 25;
  if (e <= 1) P(CX + dx, RY + dy, Z0 + dz, e > 0.7 ? (H(dx, dy, dz) < 0.5 ? "oak_leaves" : "green_wool") : "green_wool");
}
/* spiral vine wrapping the clasp */
for (var s2 = 0; s2 < 40; s2 += 0.25) {
  var an2 = s2 * 0.55, yy = RY - 10 + s2 * 0.5;
  var px = CX + Math.cos(an2) * 7.5, pz = Z0 + Math.sin(an2) * 6;
  P(px, yy, pz, "green_wool");
}
flower(CX, RY + 1, Z0 - 6, 8, -1, ["purple_wool", "red_wool", "white_wool"]);
flower(CX, RY + 1, Z0 + 6, 7, 1, ["red_wool", "white_wool", "red_wool"]);
flower(CX, RY - 11, Z0 - 3, 4, -1, WHITE);
flower(CX, RY + 13, Z0 - 2, 4, -1, PALE);

/* ---------- mirror, ground at Y=0, emit ---------- */
var minY = 1e9, keys = Object.keys(G);
for (var i = 0; i < keys.length; i++) { var c = keys[i].split(","); minY = Math.min(minY, +c[1]); }
for (i = 0; i < keys.length; i++) {
  var c2 = keys[i].split(","), X = +c2[0], Y = +c2[1] - minY, Z = +c2[2], M = G[keys[i]];
  block(X, Y, Z, M);
  if (X !== CX) block(2 * CX - X, Y, Z, M);
}
